interface BaseClass {
    name: string;
    constructorParams?: string[];
    methodParams?: Record<string, string[]>;
}

type ClassWithProps = BaseClass & { hasProps: string[] };
type ClassWithConstructorCode = BaseClass & { constructorHasCode: string };

type Class = ClassWithProps | ClassWithConstructorCode;

interface BaseFunction {
    name: string;
    params?: string[];
    methodParams?: Record<string, string[]>;
    after?: boolean;
}

type FunctionWithCode = BaseFunction & { hasCode: string };
type FunctionWithRegex = BaseFunction & { regex: RegExp };

type Function = FunctionWithCode | FunctionWithRegex;

interface Mappings {
    classes: Class[];
    functions: Function[];
    objects: { name: string; hasKeys: string[]; keyCount?: number, inline?: boolean }[];
    constants: { name: string; objectHasProps: string[] }[];
    variables: { name: string; regex: RegExp; after?: boolean; }[];
    props: { name: string; regex: RegExp; after?: boolean }[];
    collapseBlacklists: string[];
    commCodes: Record<string, string>;
    commSwitch: { name: string; regex: RegExp }[];
}

